ST.xhtml:p:
IF g_bDAOutputVolEnable THEN
  RETURN;
END_IF;

dmaster_pressure := g_dmaster_pressure * g_dGasPressurefeed;
dair_pressure := g_dair_pressure * g_dGasPressurefeed;
doxygen_pressure := g_doxygen_pressure * g_dGasPressurefeed;
dnitrogen_pressure := g_dnitogen_pressure * g_dGasPressurefeed;



IF g_bgas_enable = TRUE THEN
  bAutoSafeState := FALSE;
  nSafeState := 5;  
END_IF;

CASE nSafeState OF
  0:
    nSafeState := 0;  
  5:
    (*判断是否开启了保护气功能，然后处理*)
    IF g_bgas_enable = FALSE THEN
      IF bauto_safeEnable = TRUE AND g_nPlcState = 1 THEN
        IF g_ugas_type < 0 THEN
          g_ugas_type := 0;
        END_IF;
        bAutoSafeState := TRUE;
        dmaster_pressure := dauto_pressure * g_dGasPressurefeed;
        dair_pressure := dauto_pressure * g_dGasPressurefeed;
        doxygen_pressure := dauto_pressure * g_dGasPressurefeed;
        dnitrogen_pressure := dauto_pressure * g_dGasPressurefeed;
      ELSIF bAutoSafeState = TRUE AND g_nPlcState = 2 THEN
         IF g_ugas_type < 0 THEN
            g_ugas_type := 0;
         END_IF;
          bAutoSafeState := TRUE;
          dmaster_pressure := dauto_pressure * g_dGasPressurefeed;
          dair_pressure := dauto_pressure * g_dGasPressurefeed;
          doxygen_pressure := dauto_pressure * g_dGasPressurefeed;
          dnitrogen_pressure := dauto_pressure * g_dGasPressurefeed;
        TonCloseSafe(IN := FALSE);
        nSafeState := 10; 
      ELSIF g_nPlcState = 0 THEN
        bAutoSafeState := FALSE;
        nSafeState := 0;  
      END_IF;
    END_IF;
  10:
     IF g_ugas_type < 0 THEN
      g_ugas_type := 0;
    END_IF;
    bAutoSafeState := TRUE;
          dmaster_pressure := dauto_pressure * g_dGasPressurefeed;
          dair_pressure := dauto_pressure * g_dGasPressurefeed;
          doxygen_pressure := dauto_pressure * g_dGasPressurefeed;
          dnitrogen_pressure := dauto_pressure * g_dGasPressurefeed;  
    TonCloseSafe(IN := TRUE, PT := T#5s);
    IF TonCloseSafe.Q THEN
      bAutoSafeState := FALSE;
      nSafeState := 9;
    END_IF;
END_CASE;


IF g_bgas_enable = TRUE OR bAutoSafeState = TRUE THEN
  g_bControlGasM := FALSE;
  g_boOutPutSignalDuringCutting := TRUE;
  CASE g_ugas_type OF
    0:
      g_boMasterValve := TRUE;
      g_boAirValve := TRUE;
      g_boOxygenValve := FALSE;
      g_boNirtogenValve := FALSE;
      g_uoOxygenPressureOut := 0;
      g_uoNirtogenPressureOut := 0;

      IF g_bCheckAirDA THEN(*开启气体校准*)
        g_uoMasterPressureOut := FUN_Cailbration(g_DAAirOutputArr,g_DaAirGroupNum,dair_pressure);
        g_uoAirPressureOut := FUN_Cailbration(g_DAAirOutputArr,g_DaAirGroupNum,dair_pressure);
        g_uoSharePressureOut := FUN_Cailbration(g_DAAirOutputArr,g_DaAirGroupNum,dair_pressure);       
      ELSE
        g_uoMasterPressureOut := FUN_pressureCovertAO(dair_pressure,g_dair_maxvalue,dmax_preesure_set);
        g_uoAirPressureOut := FUN_pressureCovertAO(dair_pressure,g_dair_maxvalue,dmax_preesure_set);
        g_uoSharePressureOut := FUN_pressureCovertAO(dair_pressure,g_dair_maxvalue,dmax_preesure_set);
      END_IF;     
       g_nAheadCutGasPressureSet := g_dair_pressure;   
      g_dAheadCutGasPressureSetCur :=   dair_pressure;   
    1:
      g_boMasterValve := TRUE;
      g_boAirValve := FALSE;
      g_boOxygenValve := TRUE;
      g_boNirtogenValve := FALSE;
      g_uoAirPressureOut := 0;
      g_uoNirtogenPressureOut := 0;
      IF g_bCheckOxgenDA THEN(*开启气体校准*)
        g_uoMasterPressureOut := FUN_Cailbration(g_DAOxgenOutputArr,g_DaOxgenGroupNum,doxygen_pressure);  
        g_uoOxygenPressureOut := FUN_Cailbration(g_DAOxgenOutputArr,g_DaOxgenGroupNum,doxygen_pressure);
        g_uoSharePressureOut := FUN_Cailbration(g_DAOxgenOutputArr,g_DaOxgenGroupNum,doxygen_pressure);
      ELSE
        g_uoMasterPressureOut := FUN_pressureCovertAO(doxygen_pressure,g_doxygen_maxvalue,dmax_preesure_set);
        g_uoOxygenPressureOut := FUN_pressureCovertAO(doxygen_pressure,g_doxygen_maxvalue,dmax_preesure_set);
        g_uoSharePressureOut := FUN_pressureCovertAO(doxygen_pressure,g_doxygen_maxvalue,dmax_preesure_set);
      END_IF;
      g_nAheadCutGasPressureSet := g_doxygen_pressure;
      g_dAheadCutGasPressureSetCur :=   doxygen_pressure; 
    2:
      g_boMasterValve := TRUE;
      g_boAirValve := FALSE;
      g_boOxygenValve := FALSE;
      g_boNirtogenValve := TRUE;
      g_uoAirPressureOut := 0;
      g_uoOxygenPressureOut := 0;
      IF g_bCheckNirDA THEN(*开启气体校准*)
        g_uoMasterPressureOut := FUN_Cailbration(g_DANirOutputArr,g_DaNirGroupNum,dnitrogen_pressure);  (**改成氮气最大气压**)
        g_uoNirtogenPressureOut := FUN_Cailbration(g_DANirOutputArr,g_DaNirGroupNum,dnitrogen_pressure); 
        g_uoSharePressureOut := FUN_Cailbration(g_DANirOutputArr,g_DaNirGroupNum,dnitrogen_pressure);(**改成氮气最大气压**)
      ELSE
        g_uoMasterPressureOut := FUN_pressureCovertAO(dnitrogen_pressure,g_dnitogen_maxvalue,dmax_preesure_set);
        g_uoNirtogenPressureOut := FUN_pressureCovertAO(dnitrogen_pressure,g_dnitogen_maxvalue,dmax_preesure_set);
        g_uoSharePressureOut := FUN_pressureCovertAO(dnitrogen_pressure,g_dnitogen_maxvalue,dmax_preesure_set);
      END_IF;

      g_nAheadCutGasPressureSet := g_dnitogen_pressure;
      g_dAheadCutGasPressureSetCur :=   dnitrogen_pressure; 
    END_CASE;
ELSE
    IF NOT g_bControlGasM THEN
      g_boMasterValve := FALSE;
      g_boAirValve := FALSE;
      g_boOxygenValve := FALSE;
      g_boNirtogenValve := FALSE;
    END_IF;
    bManualOPenGas := FALSE;
    g_uoMasterPressureOut := 0;
    g_uoAirPressureOut := 0;
    g_uoOxygenPressureOut := 0;
    g_uoNirtogenPressureOut := 0;
    g_uoSharePressureOut := 0;
    g_boOutPutSignalDuringCutting := FALSE;
    g_nAheadCutGasPressureSet := 0.0;
    g_dAheadCutGasPressureSetCur := 0.0; 
END_IF;
(* gas  Alarm  DINT  dgasalarmflag:1:*)
dgasalarmflag := 0;
dgasretbooltemp := FUN_SingalLogic(g_biAirValveAlarm,bairnormallyopen) AND g_boAirValve;
TonAirAlarmDelay(IN :=dgasretbooltemp,PT := LREAL_TO_TIME(dDelayTime/1000.0));
IF TonAirAlarmDelay.Q THEN
   g_bAirPressureAlarm := TRUE;
END_IF;
IF dgasretbooltemp = FALSE THEN
  g_bAirPressureAlarm := FALSE;
END_IF;

dgasretbooltemp := FUN_SingalLogic(g_biOxygenValveAlam,boxygennormallyopen) AND g_boOxygenValve;
TonOxygenAlarmDelay(IN :=dgasretbooltemp,PT := LREAL_TO_TIME(dDelayTime/1000.0));

IF TonOxygenAlarmDelay.Q THEN
  g_bOxygenPressureAlarm := TRUE;
END_IF;
IF dgasretbooltemp = FALSE THEN
  g_bOxygenPressureAlarm := false;
  (*dgasalarmflag :=OR(dgasalarmflag,2);*)
END_IF;

dgasretbooltemp := FUN_SingalLogic(g_biNirtogenValveAlarm,bnirogennormallyopen) AND g_boNirtogenValve;
TonNirtogenAlarmDelay(IN :=dgasretbooltemp,PT := LREAL_TO_TIME(dDelayTime/1000.0));

IF TonNirtogenAlarmDelay.Q THEN
  g_bNirtogenPressureAlarm := true;

END_IF;
IF dgasretbooltemp = FALSE THEN
  g_bNirtogenPressureAlarm := false;
END_IF;
(* 气压AI反馈报警*)
IF g_bgas_enable = TRUE THEN
  CASE g_ugas_type OF
    0:
    dgasrettemp := FUN_AICovertpressure(g_uiAirFeedPressure,dAirMaxFbFromHMI,dair_maxpressurevalue);
    IF dgasrettemp <(g_dair_pressure*dair_maxfeedpercentance/100.0) THEN
      bAirMaxPressureAlarm := TRUE;
    ELSE
      bAirMaxPressureAlarm := FALSE;
    END_IF;
    TonAirAlarmDelay1(IN :=bAirMaxPressureAlarm,PT := LREAL_TO_TIME(dDelayTime/1000.0));
    IF TonAirAlarmDelay1.Q THEN
      g_bAirMaxPressureAlarm := true;
    END_IF;
    IF bAirMaxPressureAlarm = FALSE THEN
       g_bAirMaxPressureAlarm := false;
    END_IF;
    1:
    dgasrettemp := FUN_AICovertpressure(g_uiOxygenFeedPressure,dOxyMaxFbFromHMI,doxygen_maxpressurevalue);
    IF dgasrettemp <(g_doxygen_pressure*doxygen_maxfeedpercentance/100.0) THEN
      bOxygenMaxPressureAlarm := true;
    ELSE
      bOxygenMaxPressureAlarm := false;
    END_IF;
    TonOxygenAlarmDelay1(IN := bOxygenMaxPressureAlarm,PT := LREAL_TO_TIME(dDelayTime/1000.0));
    IF TonOxygenAlarmDelay1.Q THEN
      g_bOxygenMaxPressureAlarm := true;
    END_IF;
    IF bOxygenMaxPressureAlarm = FALSE THEN
      g_bOxygenMaxPressureAlarm := false;
    END_IF;
    2:
    dgasrettemp := FUN_AICovertpressure(g_uiNirtogenFeedPressure,dNitorMaxFbFromHMI,dnitogen_maxpressurevalue);
    IF dgasrettemp <(g_dnitogen_pressure*dnitogen_maxfeedpercentance/100.0) THEN
      bNirtogenMaxPressureAlarm := true;
    ELSE
      bNirtogenMaxPressureAlarm := false;
    END_IF;
     TonNirtogenAlarmDelay1(IN := bNirtogenMaxPressureAlarm,PT := LREAL_TO_TIME(dDelayTime/1000.0));
    IF TonNirtogenAlarmDelay1.Q THEN
       g_bNirtogenMaxPressureAlarm := true;
    END_IF;
    IF bNirtogenMaxPressureAlarm = FALSE THEN
       g_bNirtogenMaxPressureAlarm := false;
    END_IF;
  END_CASE;
END_IF;

(*气压反馈部分*)
g_dAirPressureFB:=UINT_TO_LREAL(g_uiAirFeedPressure)*10.0*g_dair_maxvalue/(32767.0*dmax_preesure_set);
g_dNirPressureFB:=UINT_TO_LREAL(g_uiNirtogenFeedPressure)*10.0*g_dnitogen_maxvalue/(32767.0*dmax_preesure_set);
g_dOxyPressureFB:=UINT_TO_LREAL(g_uiOxygenFeedPressure)*10.0*g_doxygen_maxvalue/(32767.0*dmax_preesure_set);
CASE g_ugas_type OF(*空气\氧气\氮气*)
  0:
    dMasterPressureFB := UINT_TO_LREAL(g_niMasterPressureFB)*10.0*g_dair_maxvalue/(32767.0*dmax_preesure_set);
    dSharePressureFB := UINT_TO_LREAL(g_niSharePressureFB)*10.0*g_dair_maxvalue/(32767.0*dmax_preesure_set);
  1:
    dMasterPressureFB := UINT_TO_LREAL(g_niMasterPressureFB)*10.0*g_doxygen_maxvalue/(32767.0*dmax_preesure_set);
    dSharePressureFB := UINT_TO_LREAL(g_niSharePressureFB)*10.0*g_doxygen_maxvalue/(32767.0*dmax_preesure_set);
  2:
    dMasterPressureFB := UINT_TO_LREAL(g_niMasterPressureFB)*10.0*g_dnitogen_maxvalue/(32767.0*dmax_preesure_set);
    dSharePressureFB := UINT_TO_LREAL(g_niSharePressureFB)*10.0*g_dnitogen_maxvalue/(32767.0*dmax_preesure_set);
END_CASE;


(*手动吹气检测电容值变化超过2000加提示*)
RtringManualOPenGas(CLK := bManualOPenGas);
IF RtringManualOPenGas.Q THEN
  dOpenGasZCoord := Axis_Z.NCTOPLC.ACTPOS;
  nZPreSensorValue := g_niZSensorValue;
END_IF;
IF bManualOPenGas AND (dOpenGasZCoord - 0.5 <Axis_Z.NCTOPLC.ACTPOS AND Axis_Z.NCTOPLC.ACTPOS < dOpenGasZCoord + 0.5) THEN
    nZCurSensorValue := UDINT_TO_DINT(g_niZSensorValue) - UDINT_TO_DINT(nZPreSensorValue);
    IF ABS(nZCurSensorValue) > 2000 THEN
      g_bTraManualOpenGasErrorAlarm := TRUE;
    END_IF;
ELSIF bManualOPenGas AND (Axis_Z.NCTOPLC.ACTPOS < dOpenGasZCoord - 0.5 AND Axis_Z.NCTOPLC.ACTPOS > dOpenGasZCoord + 0.5) THEN
      bManualOPenGas := FALSE;
END_IF;
